/**
 * The client particle of an ejected project's particle types (ADR 0080 D4, D11), in
 * `<package>/client/particle/`: a copy of the runtime's `MsmParticle`
 * (`engine-mod/src/main/java/dev/mcsupermods/runtime/client/particle/`, Minecraft 26.3, Mojang
 * names) as `ModParticle`, without the runtime's per-type counter for its client GameTest. A
 * client class: only the generated client entrypoint names it (through
 * `ModParticleProvider`). The generator's tests compare every code line with the runtime's.
 *
 * @packageDocumentation
 */

/** The source of `ModParticle.java`, copied from the runtime's `MsmParticle`. */
export function modParticleJava(clientParticlePackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MsmParticle.
package ${clientParticlePackage};

import java.util.List;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.particle.SingleQuadParticle;
import net.minecraft.client.renderer.texture.TextureAtlasSprite;
import net.minecraft.resources.Identifier;
import net.minecraft.util.LightCoordsUtil;
import net.minecraft.util.RandomSource;

/**
 * A project particle (ADR 0080 D4): one camera-facing quad. It starts with exactly the velocity of the spawn (the
 * server or the caller already randomised it), takes {@code gravity}, {@code friction}, {@code collision} (vanilla's
 * {@code hasPhysics}) and its lifetime from the {@link ParticleLook.Spec}, and lets vanilla's {@code tick()} move it;
 * after every tick it takes its frame, colour, alpha and roll from {@link ParticleLook}, and its size comes from
 * {@link #getQuadSize(float)} with the partial tick. Cut-out or translucent layer, full brightness when emissive.
 * Written from ADR 0080, never from a vanilla particle class; it touches no member that differs between 26.3 and
 * 26.4-snapshot-7 (the {@code Layer} constants are read, never constructed).
 */
public final class ModParticle extends SingleQuadParticle {
    private final Identifier id;
    private final ParticleLook.Spec spec;
    private final List<TextureAtlasSprite> sprites;
    private final int randomFrame;

    /**
     * A particle of type {@code id} at {@code x, y, z} moving at exactly {@code xd, yd, zd}; {@code sprites} is the
     * type's frames in order (never empty: {@link ModParticleProvider} checks), {@code random} picks the lifetime of a
     * range and the frame of {@code random}.
     */
    public ModParticle(
            ClientLevel level,
            double x,
            double y,
            double z,
            double xd,
            double yd,
            double zd,
            Identifier id,
            ParticleLook.Spec spec,
            List<TextureAtlasSprite> sprites,
            RandomSource random) {
        super(level, x, y, z, sprites.getFirst());
        this.id = id;
        this.spec = spec;
        this.sprites = List.copyOf(sprites);
        this.xd = xd;
        this.yd = yd;
        this.zd = zd;
        this.gravity = spec.gravity();
        this.friction = spec.friction();
        this.hasPhysics = spec.collision();
        setLifetime(ParticleLook.lifetime(spec.lifetimeMin(), spec.lifetimeMax(), random.nextDouble()));
        this.randomFrame = this.sprites.size() > 1 ? random.nextInt(this.sprites.size()) : 0;
        applyLook();
        this.oRoll = this.roll;
    }

    @Override
    public void tick() {
        super.tick();
        if (isAlive()) {
            applyLook();
        }
    }

    /** Frame, size, colour, alpha and roll for the current age. */
    private void applyLook() {
        this.oRoll = this.roll;
        this.roll = ParticleLook.roll(spec, age);
        setSprite(sprites.get(ParticleLook.frame(spec, age, lifetime, sprites.size(), randomFrame)));
        this.quadSize = ParticleLook.size(spec, age, lifetime, 0f);
        ParticleLook.Rgba rgba = ParticleLook.rgba(spec, age, lifetime);
        setColor(rgba.r(), rgba.g(), rgba.b());
        setAlpha(rgba.a());
    }

    @Override
    public float getQuadSize(float partial) {
        return ParticleLook.size(spec, age, lifetime, partial);
    }

    @Override
    protected Layer getLayer() {
        return ParticleLook.translucent(spec) ? Layer.TRANSLUCENT : Layer.OPAQUE;
    }

    @Override
    protected int getLightCoords(float partial) {
        return spec.emissive() ? LightCoordsUtil.FULL_BRIGHT : super.getLightCoords(partial);
    }

    /** The particle type's id. */
    public Identifier id() {
        return id;
    }

    /** The resolved knobs of the type. */
    public ParticleLook.Spec spec() {
        return spec;
    }

    /** How many frames the type has. */
    public int spriteCount() {
        return sprites.size();
    }

    /** Whether it is drawn in the translucent layer (else cut-out). */
    public boolean translucentLayer() {
        return ParticleLook.translucent(spec);
    }
}
`;
}
